public class InnerRuntimeCustomJWTAuthorizerConfigurationFactory(Action<Humidifier.BedrockAgentCore.RuntimeTypes.CustomJWTAuthorizerConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.RuntimeTypes.CustomJWTAuthorizerConfiguration>
{

    internal InnerRuntimeAllowedWorkloadConfigurationFactory AllowedWorkloadConfigurationFactory { get; set; }

    internal InnerRuntimePrivateEndpointFactory PrivateEndpointFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.RuntimeTypes.CustomJWTAuthorizerConfiguration Create()
    {
        var customJWTAuthorizerConfigurationResult = CreateCustomJWTAuthorizerConfiguration();
        factoryAction?.Invoke(customJWTAuthorizerConfigurationResult);

        return customJWTAuthorizerConfigurationResult;
    }

    private Humidifier.BedrockAgentCore.RuntimeTypes.CustomJWTAuthorizerConfiguration CreateCustomJWTAuthorizerConfiguration()
    {
        var customJWTAuthorizerConfigurationResult = new Humidifier.BedrockAgentCore.RuntimeTypes.CustomJWTAuthorizerConfiguration();

        return customJWTAuthorizerConfigurationResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.RuntimeTypes.CustomJWTAuthorizerConfiguration result)
    {
        base.CreateChildren(result);

        result.AllowedWorkloadConfiguration ??= AllowedWorkloadConfigurationFactory?.Build();
        result.PrivateEndpoint ??= PrivateEndpointFactory?.Build();
    }

} // End Of Class

